using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.Json;
using System.Text.RegularExpressions;
using Microsoft.Extensions.AI;
using OpenAI;

// ── Configuration ──────────────────────────────────────────────────────────────

var openAiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

var topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptForTopic();

Console.WriteLine($"\n🔍 Researching: {topic}\n");

// ── Build the AI chat client with tools ────────────────────────────────────────

var notes = new NoteStore();

IChatClient client = new ChatClientBuilder(
        new OpenAIClient(openAiKey).GetChatClient(model).AsIChatClient())
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(
            ([Description("The search query")] string query) => WebSearchTool.SearchAsync(query),
            "web_search",
            "Searches the web for information on a given query and returns relevant snippets."),

        AIFunctionFactory.Create(
            ([Description("Title for the note")] string title,
             [Description("Content of the note")] string content) =>
            {
                notes.Add(title, content);
                return $"Note saved: \"{title}\"";
            },
            "save_note",
            "Saves a research note with a title and content for later reference."),

        AIFunctionFactory.Create(
            () => notes.GetAll(),
            "get_notes",
            "Retrieves all previously saved research notes."),
    ],
};

// ── Agent loop ─────────────────────────────────────────────────────────────────

List<ChatMessage> messages =
[
    new(ChatRole.System, """
        You are a research agent. Your job is to thoroughly research the given topic
        using the web_search tool. Follow these steps:

        1. Search for the topic from multiple angles (at least 3 different searches).
        2. After each search, save important findings using the save_note tool.
        3. Once you have gathered enough information, retrieve your notes with get_notes.
        4. Write a comprehensive summary of your findings with sections, key facts, and sources.

        Be thorough but concise. Cite specific facts and data points you discover.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}"),
];

Console.WriteLine("Agent is working…\n");

var response = await client.GetResponseAsync(messages, chatOptions);

Console.WriteLine("═══════════════════════════════════════════════════════════");
Console.WriteLine("                     RESEARCH SUMMARY");
Console.WriteLine("═══════════════════════════════════════════════════════════\n");
Console.WriteLine(response.Text);
Console.WriteLine("\n═══════════════════════════════════════════════════════════");
Console.WriteLine($"📝 Notes collected: {notes.Count}");
Console.WriteLine("═══════════════════════════════════════════════════════════");

// ── Helpers ────────────────────────────────────────────────────────────────────

static string PromptForTopic()
{
    Console.Write("Enter a research topic: ");
    var input = Console.ReadLine()?.Trim();
    return string.IsNullOrEmpty(input)
        ? throw new InvalidOperationException("A research topic is required.")
        : input;
}

// ── Web Search Tool ────────────────────────────────────────────────────────────

static partial class WebSearchTool
{
    public static async Task<string> SearchAsync(string query)
    {
        Console.WriteLine($"  🌐 Searching: \"{query}\"");

        try
        {
            using var http = new HttpClient();
            http.DefaultRequestHeaders.UserAgent.ParseAdd(
                "Mozilla/5.0 (compatible; ResearchAgent/1.0)");

            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://html.duckduckgo.com/html/?q={encoded}";
            var html = await http.GetStringAsync(url);

            var results = ParseSearchResults(html);

            if (results.Count == 0)
                return "No results found for the query.";

            var sb = new StringBuilder();
            sb.AppendLine($"Search results for: \"{query}\"\n");
            foreach (var (title, snippet, link) in results.Take(5))
            {
                sb.AppendLine($"• {title}");
                sb.AppendLine($"  {snippet}");
                sb.AppendLine($"  Link: {link}");
                sb.AppendLine();
            }

            return sb.ToString();
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    private static List<(string Title, string Snippet, string Link)> ParseSearchResults(string html)
    {
        var results = new List<(string, string, string)>();

        // Extract result blocks from DuckDuckGo HTML
        var resultMatches = ResultBlockRegex().Matches(html);

        foreach (Match block in resultMatches)
        {
            var blockHtml = block.Value;

            var titleMatch = TitleRegex().Match(blockHtml);
            var snippetMatch = SnippetRegex().Match(blockHtml);
            var linkMatch = LinkRegex().Match(blockHtml);

            var title = titleMatch.Success ? StripHtml(titleMatch.Groups[1].Value) : "Untitled";
            var snippet = snippetMatch.Success ? StripHtml(snippetMatch.Groups[1].Value) : "";
            var link = linkMatch.Success ? ExtractUrl(linkMatch.Groups[1].Value) : "";

            if (!string.IsNullOrWhiteSpace(snippet))
                results.Add((title, snippet, link));
        }

        return results;
    }

    private static string StripHtml(string html) =>
        WebUtility.HtmlDecode(HtmlTagRegex().Replace(html, "")).Trim();

    private static string ExtractUrl(string rawUrl)
    {
        var decoded = WebUtility.UrlDecode(rawUrl);
        var match = UdduckhrefRegex().Match(decoded);
        return match.Success ? match.Groups[1].Value : decoded;
    }

    [GeneratedRegex(@"<div class=""result results_links[\s\S]*?</div>\s*</div>\s*</div>",
        RegexOptions.IgnoreCase)]
    private static partial Regex ResultBlockRegex();

    [GeneratedRegex(@"class=""result__a""[^>]*>([\s\S]*?)</a>", RegexOptions.IgnoreCase)]
    private static partial Regex TitleRegex();

    [GeneratedRegex(@"class=""result__snippet""[^>]*>([\s\S]*?)</(?:td|span|div)>",
        RegexOptions.IgnoreCase)]
    private static partial Regex SnippetRegex();

    [GeneratedRegex(@"class=""result__a""\s+href=""([^""]+)""", RegexOptions.IgnoreCase)]
    private static partial Regex LinkRegex();

    [GeneratedRegex(@"<[^>]+>")]
    private static partial Regex HtmlTagRegex();

    [GeneratedRegex(@"uddg=([^&]+)")]
    private static partial Regex UdduckhrefRegex();
}

// ── Note Store ─────────────────────────────────────────────────────────────────

class NoteStore
{
    private readonly List<Note> _notes = [];

    public int Count => _notes.Count;

    public void Add(string title, string content)
    {
        _notes.Add(new Note(title, content, DateTime.UtcNow));
        Console.WriteLine($"  📝 Note saved: \"{title}\"");
    }

    public string GetAll()
    {
        if (_notes.Count == 0) return "No notes saved yet.";

        var sb = new StringBuilder();
        for (var i = 0; i < _notes.Count; i++)
        {
            var n = _notes[i];
            sb.AppendLine($"[{i + 1}] {n.Title}");
            sb.AppendLine($"    {n.Content}");
            sb.AppendLine();
        }

        return sb.ToString();
    }
}

